<div class="card mt-4"><div class="card-header">Payments</div><div class="table-responsive"><table class="table mb-0 align-middle"><thead><tr><th>No.</th><th>Date</th><th>Account</th><th>Method</th><th>Reference</th><th class="text-end">Amount</th><th>Status</th><th></th></tr></thead><tbody>
  <?php foreach ($payments as $p): ?><tr class="<?= $p['status'] === 'voided' ? 'row-muted' : '' ?>"><td><?= e($p['payment_no']) ?></td><td><?= e(fdate($p['payment_date'])) ?></td><td><?= e($p['account_name']) ?></td><td><?= e(label_of($p['method'])) ?></td><td><?= e($p['reference_no']) ?></td><td class="text-end"><?= e(money($p['amount'], false)) ?></td><td><?= status_badge($p['status']) ?></td>
    <td class="text-end"><?php if ($p['status'] === 'posted' && can('payments.manage')): ?><form class="d-inline" method="post" action="<?= e(url('admin/payments/' . $p['id'] . '/cancel')) ?>" data-cancel="Void this payment?" data-cancel-label="Void"><?= csrf_field() ?><input type="hidden" name="reason"><button class="btn btn-sm btn-link text-danger p-0">Void</button></form><?php endif; ?></td></tr><?php endforeach; ?>
  <?php if (!$payments): ?><tr><td colspan="8" class="text-body-secondary">No payments recorded yet.</td></tr><?php endif; ?>
</tbody></table></div></div>
